function scoreOf(s){let sc=rankingScore(s);return state.sortRanking==='reactions'?sc.reactions:state.sortRanking==='questions'?sc.questions:Math.round((sc.reactions/Math.max(sc.classes,1))*4+sc.questions*3+sc.checks*2+sc.polls);}
