function attendanceTable(){let w=webinar(state.selectedClass),batch=STUDENTS.filter(s=>s.batch===w.batch),q=state.search.trim().toLowerCase();let rows=batch.filter(s=>!q||`${s.name} ${s.id}`.toLowerCase().includes(q)).slice(0,60);return `<div class="table-wrap"><table><thead><tr><th>Student</th><th>First join</th><th>Last leave</th><th>Connected</th><th>Attendance</th><th>Result</th><th></th></tr></thead><tbody>${rows.map(s=>{let a=attendanceFor(s.id,w.id);return `<tr><td><span class="student-name">${safe(s.name)}</span><div class="muted text-xs">${safe(s.id)}</div></td><td>${timeAt('14:00',a.firstJoin||0)}</td><td>${timeAt('14:00',a.lastLeave||0)}</td><td><strong>${a.connected} min</strong> / ${w.minutes}</td><td><div class="flex"><div class="progress-track" style="width:66px"><div class="progress-fill" style="width:${clamp(a.rate,0,100)}%"></div></div><b>${fmtPct(a.rate)}</b></div></td><td>${presentStatus(a.status)}</td><td><button class="table-action" data-action="open-student:${safe(s.id)}">Open →</button></td></tr>`}).join('')}</tbody></table></div>${rows.length===0?'<div class="empty">No students match that search.</div>':''}`}
